// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

/**
 * The decode cache in {@link LmdbNativeValueCodec} is read and written concurrently by the parallel kernel workers,
 * which all share one codec instance. Its original publication protocol (invalidate id, publish value, re-publish id
 * across two atomic arrays) is only safe for a single writer: two writers colliding on one direct-mapped slot can
 * interleave as {@code W1:ids=0; W1:values=X; W2:ids=0; W2:values=Y; W2:ids=Y; W1:ids=X}, leaving the slot claiming id
 * X while holding Y's decoded value. Every later reader of X then receives Y's value until the slot is next overwritten
 * — observed in the wild as the LIBRARY query 3 COUNT(DISTINCT) returning 7956..7960 instead of 7958 (2026-08-16 theme
 * benchmark run): one member's name string decoded as a different member's name, flipping a MINUS CONTAINS filter both
 * ways.
 *
 * This test hammers one shared codec from many threads over inlined integer ids (no value store required) and asserts
 * every decode returns the value belonging to the requested id.
 */
class LmdbNativeValueCodecConcurrencyTest {

	private static long inlinedIntegerId(long value) {
		long zigzag = (value << 1) ^ (value >> 63);
		return ValueIds.createId(ValueIds.T_INTEGER, zigzag);
	}

	@Test
	@Timeout(120)
	void concurrentDecodesNeverReturnAnotherIdsValue() throws Exception {
		LmdbNativeValueCodec codec = new LmdbNativeValueCodec(null);
		int idCount = 1 << 13;
		long[] ids = new long[idCount];
		String[] expected = new String[idCount];
		for (int i = 0; i < idCount; i++) {
			ids[i] = inlinedIntegerId(i);
			expected[i] = Long.toString(i);
		}
		// sanity: single-threaded decode agrees with the expectation before the stress begins
		for (int i = 0; i < idCount; i++) {
			Assertions.assertEquals(expected[i], codec.decode(ids[i]).label(), "single-threaded decode of id " + i);
		}
		int threads = 12;
		int iterationsPerThread = 400_000;
		ExecutorService pool = Executors.newFixedThreadPool(threads);
		CountDownLatch start = new CountDownLatch(1);
		List<Future<String>> results = new ArrayList<>(threads);
		try {
			for (int t = 0; t < threads; t++) {
				results.add(pool.submit(() -> {
					ThreadLocalRandom random = ThreadLocalRandom.current();
					start.await();
					for (int i = 0; i < iterationsPerThread; i++) {
						int pick = random.nextInt(idCount);
						LmdbNativeValueCodec.DecodedValue decoded = codec.decode(ids[pick]);
						String label = decoded.label();
						if (!expected[pick].equals(label)) {
							return "decode of inlined integer " + pick + " returned '" + label
									+ "' (expected '" + expected[pick] + "') on iteration " + i;
						}
					}
					return null;
				}));
			}
			start.countDown();
			for (Future<String> result : results) {
				String failure = result.get(110, TimeUnit.SECONDS);
				Assertions.assertNull(failure, () -> failure);
			}
		} finally {
			pool.shutdownNow();
		}
	}
}
